from pathlib import Path
p=Path('README.md'); s=p.read_text(encoding='utf-8-sig')
s=s.replace('- A compatible text-generation API credential and model for transformations. No provider is enabled by default.', '- For real AI transformations, a Gemini API key is required. The app defaults to a Gemini OpenAI-compatible endpoint and `gemini-3.5-flash-lite`.')
s=s.replace('Edit `backend/.env`, set a strong random `FLASK_SECRET_KEY`, and configure `AI_API_KEY` and `AI_MODEL`. The API defaults to OpenAI\'s Chat Completions-compatible endpoint. To load the optional dotenv file, run:', 'Edit `backend/.env` and set `AI_API_KEY` to a Gemini key. The default base URL and model are preconfigured in `backend/.env.example`; leave the Google Cloud project on the free tier and do not enable billing. Flask loads `backend/.env` relative to `backend/app.py` on startup. Then run:')
s=s.replace('| `AI_BASE_URL` | Provider API root; defaults to `https://api.openai.com/v1`. |', '| `AI_BASE_URL` | Defaults to Gemini’s OpenAI-compatible endpoint: `https://generativelanguage.googleapis.com/v1beta/openai/`. |')
s=s.replace('| `AI_MODEL` | Provider model identifier; configured once, not embedded in app logic. |', '| `AI_MODEL` | Defaults to `gemini-3.5-flash-lite`, currently listed with free-tier input and output. |')
start=s.find('The backend uses the Chat Completions request format documented by OpenAI.')
end=s.find('\n\n## Local-only',start)
if start>=0 and end>start:
 s=s[:start]+('The backend uses the Chat Completions-compatible REST interface. Google documents this compatibility, including the Gemini endpoint and model names, in its [OpenAI compatibility guide](https://ai.google.dev/gemini-api/docs/openai/). Google’s [pricing page](https://ai.google.dev/gemini-api/docs/pricing) currently lists `gemini-3.5-flash-lite` with free-tier text input and output, subject to account, region, rate, and quota limits. It still requires an API key. Create the key in [Google AI Studio](https://aistudio.google.com/apikey) for a project with no billing enabled; do not select or attach a paid-billing project. Free-tier submitted content may be used by Google to improve products according to its pricing disclosure, so avoid confidential messages unless that is acceptable. The app never turns on billing. Provider credentials stay in `backend/.env`, which is gitignored. If the free quota is exhausted, the app returns a retry-later message; it will not upgrade the account.')+s[end:]
p.write_text(s,encoding='utf-8')
